<patch>
diff --git a/src/policy/feerate.h b/src/policy/feerate.h
index cd0f4454f9..00a507dafa 100644
--- a/src/policy/feerate.h
+++ b/src/policy/feerate.h
@@ -80,7 +80,16 @@ public:
     friend CFeeRate operator*(const CFeeRate& f, int a) { return CFeeRate(a * f.m_feerate.fee, f.m_feerate.size); }
     friend CFeeRate operator*(int a, const CFeeRate& f) { return CFeeRate(a * f.m_feerate.fee, f.m_feerate.size); }

-    SERIALIZE_METHODS(CFeeRate, obj) { READWRITE(obj.m_feerate.fee, obj.m_feerate.size); }
+    SERIALIZE_METHODS(CFeeRate, obj)
+    {
+        READWRITE(obj.m_feerate.fee, obj.m_feerate.size);
+        // Reject values the constructors cannot produce. A negative size
+        // violates the FeeFrac::EvaluateFee precondition, and a zero size with
+        // a nonzero fee compares as an infinite feerate.
+        SER_READ(obj, if (obj.m_feerate.size < 0 || (obj.m_feerate.size == 0 && obj.m_feerate.fee != 0)) {
+            throw std::ios_base::failure("CFeeRate::Unserialize: invalid fee and size");
+        });
+    }
 };

 #endif // BITCOIN_POLICY_FEERATE_H
diff --git a/src/test/amount_tests.cpp b/src/test/amount_tests.cpp
index bb8ece36fc..ac00e4e11e 100644
--- a/src/test/amount_tests.cpp
+++ b/src/test/amount_tests.cpp
@@ -4,8 +4,12 @@

 #include <consensus/amount.h>
 #include <policy/feerate.h>
+#include <streams.h>
+#include <test/util/common.h>

+#include <ios>
 #include <limits>
+#include <utility>

 #include <boost/test/unit_test.hpp>

@@ -178,4 +182,26 @@ BOOST_AUTO_TEST_CASE(ToStringTest)
     BOOST_CHECK_EQUAL(feeRate.ToString(FeeRateFormat::SAT_VB), "-100000.001 sat/vB");
 }

+BOOST_AUTO_TEST_CASE(SerializeTest)
+{
+    // Values the constructors produce round-trip unchanged.
+    for (const CFeeRate& feerate : {CFeeRate{}, CFeeRate{1000}, CFeeRate{-1000}, CFeeRate{CAmount{5}, 3}}) {
+        DataStream stream;
+        stream << feerate;
+        CFeeRate result{1};
+        stream >> result;
+        BOOST_CHECK(result.GetFeePerVSize() == feerate.GetFeePerVSize());
+        BOOST_CHECK(stream.empty());
+    }
+
+    // Values the constructors cannot produce are rejected instead of reaching
+    // FeeFrac::EvaluateFee with a non-positive size.
+    for (const auto& [fee, size] : {std::pair<int64_t, int32_t>{1000, -1}, {0, -1}, {5, 0}, {-5, 0}}) {
+        DataStream stream;
+        stream << fee << size;
+        CFeeRate result;
+        BOOST_CHECK_EXCEPTION(stream >> result, std::ios_base::failure, HasReason{"CFeeRate::Unserialize: invalid fee and size"});
+    }
+}
+
 BOOST_AUTO_TEST_SUITE_END()

</patch>
